pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        vm.deal(address(this), 2 ether);
        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(this).balance;
        c.withdrawAll(address(this));
        // Reference: balance increases by 1 ether (transfer to this)
        // Bug: balance unchanged (transfer to address(0))
        assertTrue(address(this).balance > balanceBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: send 1 ether to the contract
        vm.deal(address(c), 1 ether);
        // Record balance of test contract before call
        uint256 balanceBefore = address(this).balance;
        // As owner, call withdrawAll with recipient = address(this)
        c.withdrawAll(address(this));
        // After reference call: recipient (this) receives the 1 ether, so balance should be balanceBefore + 1 ether
        // After buggy call: address(0) receives, so this.balance unchanged
        assertTrue(address(this).balance == balanceBefore + 1 ether);
    }
}

